package com.meterflow.invoicing;
import com.meterflow.subscriptions.*;import com.meterflow.catalogue.*;import com.meterflow.metering.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.time.*;import java.math.*;import java.util.*;
@Service public class BillingService {
 private final SubscriptionRepository subs;private final PlanRepository plans;private final UsageEventRepository events;private final InvoiceRepository invoices;private final InvoiceLineRepository lines;private final PricingService pricing;
 public BillingService(SubscriptionRepository s,PlanRepository p,UsageEventRepository e,InvoiceRepository i,InvoiceLineRepository l,PricingService pr){subs=s;plans=p;events=e;invoices=i;lines=l;pricing=pr;}
 @Transactional public Map<String,Object> run(String period){YearMonth ym;try{ym=YearMonth.parse(period);}catch(Exception e){throw new IllegalArgumentException("period must be YYYY-MM");}int created=0,existing=0;for(var sub:subs.findByStatus("ACTIVE")){String customer=sub.getCustomerId();if(invoices.findByCustomerIdAndPeriod(customer,period).isPresent()){existing++;continue;}var plan=plans.findById(sub.getPlanId()).orElseThrow();Instant from=ym.atDay(1).atStartOfDay(ZoneOffset.UTC).toInstant();Instant to=ym.plusMonths(1).atDay(1).atStartOfDay(ZoneOffset.UTC).toInstant();var usage=events.findMetricWindow(customer,plan.getMetric(),from,to).stream().map(UsageEvent::getQuantity).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal amount=pricing.calculate(plan,usage);BigDecimal tax=BigDecimal.ZERO;var inv=invoices.save(new InvoiceBuilder().customer(customer).period(period).currency(plan.getCurrency()).subtotal(amount).tax(tax).build());lines.save(new InvoiceLine(inv.getId(),plan.getMetric(),usage,plan.getUnitPrice(),amount,"Plan "+plan.getPlanKey()+" v"+plan.getVersion()+": flat + per-unit after free allowance; minimum commitment applied","VAT 0% (demo default; configure tax before real billing)"));created++;}return Map.of("period",period,"created",created,"alreadyExisted",existing,"status","completed");}
}
